#!/usr/bin/env node
/* global process, console */
/**
 * identify-icons.mjs: identify every <svg> icon in the live DOM snapshots by its geometry
 * and write src/products/tulvo/icons.md.
 *
 *   node src/products/tulvo/tools/identify-icons.mjs [--dom <dir>] [--out <file>]
 *
 * Each snapshot SVG's shapes (tag + geometry attributes, ignoring stroke/fill styling) are
 * compared with every iconNode in the installed lucide-react package. Non-lucide SVGs are
 * matched against the app's own icons (icons/app-icons.tsx, generated by gen-app-icons.py)
 * or classified (third-party brand logo, chart, browser-extension overlay).
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const STUDIO = path.resolve(__dirname, "../../../..");
const args = process.argv.slice(2);
const arg = (k, d) => (args.includes(k) ? args[args.indexOf(k) + 1] : d);
const DOM = arg("--dom", "research/ui-live/dom");
const OUT = arg("--out", path.resolve(__dirname, "../icons.md"));

// ---------------------------------------------------------------- lucide iconNodes
const pkgDir = path.join(STUDIO, "node_modules/lucide-react");
const lucideVersion = JSON.parse(fs.readFileSync(path.join(pkgDir, "package.json"), "utf8")).version;
const iconsDir = path.join(pkgDir, "dist/esm/icons");
const GEOM_SKIP = new Set(["key", "stroke", "fill", "stroke-width", "strokeWidth", "stroke-linecap", "stroke-linejoin", "class", "fill-rule", "clip-rule", "fillRule", "clipRule"]);
const norm = (shapes) =>
  JSON.stringify(
    shapes.map(([tag, a]) => [tag, Object.fromEntries(Object.keys(a).filter((k) => !GEOM_SKIP.has(k)).sort().map((k) => [k, String(a[k])]))])
  );
const lucideByShape = new Map();
for (const f of fs.readdirSync(iconsDir)) {
  if (!/\.m?js$/.test(f)) continue;
  const src = fs.readFileSync(path.join(iconsDir, f), "utf8");
  const m = src.match(/const __iconNode = (\[[\s\S]*?\]);\n/);
  const exp = src.match(/createLucideIcon\("([^"]+)"/);
  if (!m || !exp) continue;
  const node = Function(`return ${m[1]}`)();
  const k = norm(node);
  if (!lucideByShape.has(k)) lucideByShape.set(k, []);
  lucideByShape.get(k).push({ file: f.replace(/\.m?js$/, ""), exportName: exp[1] });
}

// ---------------------------------------------------------------- app icons (app-icons.tsx)
const appIconsSrc = fs.readFileSync(path.resolve(__dirname, "../icons/app-icons.tsx"), "utf8");
const appIcons = [];
for (const m of appIconsSrc.matchAll(/export const (\w+): React\.FC<AppIconProps>[\s\S]*?<\/svg>/g)) {
  const firstD = (m[0].match(/\sd="([^"]+)"/) || [])[1];
  if (firstD) appIcons.push({ name: m[1], firstD });
}

// ---------------------------------------------------------------- DOM svgs
const attrsOf = (s) => Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map((x) => [x[1].toLowerCase(), x[2]]));
const textAround = (html, idx, dir) => {
  const slice = dir > 0 ? html.slice(idx, idx + 1500) : html.slice(Math.max(0, idx - 1500), idx);
  const t = slice
    .replace(/<svg[\s\S]*?<\/svg>/g, " ")
    .replace(/<[^>]+>/g, "|")
    .split("|")
    .map((x) => x.trim())
    .filter((x) => x && !/[<>="]/.test(x));
  return scrub((dir > 0 ? t[0] : t[t.length - 1]) || "");
};
// The snapshots hold AI sample records (possibly-real brands) and account details: never copy them.
const scrub = (s) => (/peaktrail|northstar|glowup|tulvo production|hidingpost|@|creator studio rehearsal/i.test(s) ? "(sample data)" : s);
const found = new Map(); // key -> record
for (const file of fs.readdirSync(DOM).filter((f) => f.endsWith(".html")).sort()) {
  const html = fs.readFileSync(path.join(DOM, file), "utf8");
  for (const m of html.matchAll(/<svg\b([^>]*)>([\s\S]*?)<\/svg>/g)) {
    const a = attrsOf(m[1]);
    const shapes = [...m[2].matchAll(/<(path|circle|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/?>/g)].map((s) => [s[1], attrsOf(s[2])]);
    const cls = a.class || "";
    const lucideClass = (cls.match(/\blucide-([a-z0-9-]+)/) || [])[1];
    const tabler = (cls.match(/\btabler-icon-([a-z0-9-]+)/) || [])[1];
    const key = norm(shapes) + "|" + (lucideClass || tabler || "");
    const ctx = scrub(a["aria-label"] || "") || textAround(html, m.index + m[0].length, 1) || textAround(html, m.index, -1);
    if (!found.has(key)) found.set(key, { shapes, cls, lucideClass, tabler, attrs: a, files: new Set(), ctx: new Set(), count: 0, classes: new Set() });
    const r = found.get(key);
    r.count++;
    r.files.add(file.replace(/\.html$/, ""));
    if (ctx && r.ctx.size < 4) r.ctx.add(ctx.slice(0, 40));
    r.classes.add(cls.replace(/\blucide(-[a-z0-9-]+)?\b/g, "").replace(/\s+/g, " ").trim());
  }
}

// ---------------------------------------------------------------- classify + write
const rows = { lucide: [], app: [], brand: [], other: [] };
for (const r of found.values()) {
  const lucide = lucideByShape.get(norm(r.shapes));
  const firstD = (r.shapes.find(([t]) => t === "path") || [null, {}])[1].d || "";
  const app = appIcons.find((x) => x.firstD === firstD);
  if (r.lucideClass && lucide) rows.lucide.push({ ...r, lucide });
  else if (app) rows.app.push({ ...r, app: app.name });
  else if (/^(slack|notion|google)$/i.test([...r.ctx][0] || "")) rows.brand.push(r);
  else if (r.lucideClass && !lucide) rows.other.push({ ...r, why: `class lucide-${r.lucideClass} but no lucide-react@${lucideVersion} icon has this geometry` });
  else if (lucide) rows.lucide.push({ ...r, lucide, noClass: true });
  else if (/recharts/.test(r.cls)) rows.other.push({ ...r, why: "recharts chart surface (not an icon)" });
  else if (/M0 0 L0 18 L4\.5 14/.test(firstD)) rows.other.push({ ...r, why: "Claude-in-Chrome agent cursor overlay (browser extension, not the app): ignore" });
  else rows.other.push({ ...r, why: "unclassified" });
}
const fmtSet = (s, n = 3) => [...s].slice(0, n).join(", ");
const esc = (s) => String(s).replace(/\|/g, "\\|");
rows.lucide.sort((a, b) => a.lucide[0].exportName.localeCompare(b.lucide[0].exportName));

let md = `# Tulvo UI icons (identified from the live DOM)

GENERATED by \`node src/products/tulvo/tools/identify-icons.mjs\` from \`research/ui-live/dom/*.html\`. Do not edit by hand.

How: every \`<svg>\` in the 14 snapshots was compared, shape by shape (tag + geometry attributes, ignoring stroke/fill
styling), with every icon in the installed **lucide-react@${lucideVersion}** (pinned exact in package.json). That version
was chosen because it reproduces the app's icons exactly: versions 0.469–0.479 match every lucide-classed SVG
geometry, and only versions before 0.487 emit the app's single class form (\`lucide-trash2\`, not \`lucide-trash-2\`).

Use: \`import { Plus } from "lucide-react"\` and pass the DOM's extra classes, e.g. \`<Plus className="h-4 w-4 text-muted-foreground" />\`.
lucide-react adds \`lucide lucide-<name>\` itself. Copy non-default \`stroke-width\` (e.g. Deploy/Data Templates use 1.5) and
\`width/height\` attributes (e.g. the workspace chevron is \`size={16}\`).

## Lucide icons (${rows.lucide.length})

| lucide-react export | DOM class | uses | where (snapshots) | example context | extra classes seen |
|---|---|---|---|---|---|
`;
for (const r of rows.lucide) {
  const sw = r.attrs["stroke-width"] && r.attrs["stroke-width"] !== "2" ? ` (stroke-width ${r.attrs["stroke-width"]})` : "";
  md += `| \`${r.lucide.map((x) => x.exportName).join("` / `")}\`${sw} | ${r.noClass ? "(no lucide class)" : `lucide-${r.lucideClass}`} | ${r.count} | ${fmtSet(r.files, 4)}${r.files.size > 4 ? " …" : ""} | ${esc(fmtSet(r.ctx, 2))} | ${esc(fmtSet(r.classes, 2)).slice(0, 140)} |\n`;
}
md += `
## App's own icons → \`icons/app-icons.tsx\` (${rows.app.length})

Path-for-path copies generated by \`tools/gen-app-icons.py\` (tabler layout-grid / file-text, custom Home, Trash, Tulvo AI sparkle, ...).

| component | DOM class | uses | where | example context |
|---|---|---|---|---|
`;
for (const r of rows.app) md += `| \`${r.app}\` | ${esc(r.cls || "(none)").slice(0, 90)} | ${r.count} | ${fmtSet(r.files, 4)} | ${esc(fmtSet(r.ctx, 2))} |\n`;
md += `
## Third-party brand logos → \`<IntegrationLogoSlot/>\` (${rows.brand.length})

The live sidebar shows the Slack, Notion and Google logos (18x18). The ad shows other companies' names only as plain
text, never logos: these slots default to a neutral placeholder tile (\`icons/IntegrationLogoSlot.tsx\`, prop \`logo\` to override).

| vendor (text) | DOM class | uses |
|---|---|---|
`;
for (const r of rows.brand) md += `| ${esc(fmtSet(r.ctx, 1))} | ${esc(r.cls)} | ${r.count} |\n`;
md += `
## Not icons / ignored (${rows.other.length})

| what | DOM class | uses | where |
|---|---|---|---|
`;
for (const r of rows.other) md += `| ${esc(r.why)} | ${esc(r.cls || "(none)").slice(0, 80)} | ${r.count} | ${fmtSet(r.files, 3)} |\n`;
md += `
Note: \`lucide-kanban-layout\` (board view switcher) is an app-made icon built with lucide's \`createLucideIcon\`; it is not in
lucide-react, so it lives in \`app-icons.tsx\` as \`KanbanLayoutIcon\`.
`;
fs.writeFileSync(OUT, md);
console.log(`identify-icons: ${rows.lucide.length} lucide, ${rows.app.length} app, ${rows.brand.length} brand, ${rows.other.length} other -> ${path.relative(process.cwd(), OUT)}`);
